func (app *App[P]) ForPrincipal(ctx context.Context, principal P) (*Caller[P], error) {
	inner, err := app.runtime.ForPrincipal(ctx, principal)
	if err != nil {
		return nil, err
	}
	result := &Caller[P]{runtime: inner}
	result.Teams = CallerTeamClient[P]{runtime: inner}
	result.Invites = CallerInviteClient[P]{runtime: inner}
	return result, nil
}

func golemGeneratedOperationCaller[P any](inner *golemruntime.Caller[P, Actor]) *Caller[P] {
	result := &Caller[P]{runtime: inner}
	result.Teams = CallerTeamClient[P]{runtime: inner}
	result.Invites = CallerInviteClient[P]{runtime: inner}
	return result
}

// Mutate runs resolver, a custom mutation declared with golem.Mutation,
// exactly as GraphQL dispatch runs it: resolver receives a caller carrying
// the Within grants of that operation, observed as mutation.custom, and
// those grants end when it returns. A function that is not a generated
// custom mutation is refused with P5_CUSTOM_OPERATION before anything runs.
func Mutate[P, Args, R any](ctx context.Context, caller *Caller[P], resolver func(context.Context, *Caller[P], Args) (R, error), arguments Args) (R, error) {
	var inner *golemruntime.Caller[P, Actor]
	if caller != nil {
		inner = caller.runtime
	}
	return golemruntime.RunCallerOperation(ctx, inner, resolver, golemGeneratedOperationCaller[P], arguments)
}

func (app *App[P]) System() System[P] {
	inner := app.runtime.System()
	result := System[P]{runtime: inner}
	result.Teams = SystemTeamClient[P]{runtime: inner}
	result.Invites = SystemInviteClient[P]{runtime: inner}
	return result
}

func (caller *Caller[P]) Transaction(ctx context.Context, callback func(*CallerTx[P]) error) error {
	if caller == nil {
		return golemruntime.CallerTransaction(ctx, (*golemruntime.Caller[P, Actor])(nil), nil)
	}
	if callback == nil {
		return golemruntime.CallerTransaction(ctx, caller.runtime, nil)
	}
	return golemruntime.CallerTransaction(ctx, caller.runtime, func(inner *golemruntime.CallerTx[P, Actor]) error {
		result := &CallerTx[P]{runtime: inner}
		result.Teams = CallerTxTeamClient[P]{runtime: inner}
		result.Invites = CallerTxInviteClient[P]{runtime: inner}
		return callback(result)
	})
}
func (transaction *CallerTx[P]) Enqueue(ctx context.Context, pending queue.Pending) (queue.JobID, error) {
	if transaction == nil {
		return golemruntime.CallerTxEnqueue(ctx, (*golemruntime.CallerTx[P, Actor])(nil), pending)
	}
	return golemruntime.CallerTxEnqueue(ctx, transaction.runtime, pending)
}

// SystemEscape leaves the authorized path. It returns the unrestricted
// system clients for the caller transaction itself, so their reads and
// writes run inside that transaction and commit or roll back with every
// caller write in it.
//
// Nothing performed through them is policy-checked. No caller rule, field
// restriction, or row predicate applies, exactly as if the write had been
// made by App.System. Use it only for a value the application owns and no
// client may set, and keep the call at the site that needs it: every call
// is observed as transaction.system_escape.
func SystemEscape[P any](transaction *CallerTx[P]) *SystemTx[P] {
	var inner *golemruntime.SystemTx[P, Actor]
	if transaction != nil {
		inner = golemruntime.CallerTxSystem(transaction.runtime)
	}
	result := &SystemTx[P]{runtime: inner}
	result.Teams = SystemTxTeamClient[P]{runtime: inner}
	result.Invites = SystemTxInviteClient[P]{runtime: inner}
	return result
}

func (system System[P]) Transaction(ctx context.Context, callback func(*SystemTx[P]) error) error {
	if callback == nil {
		return golemruntime.SystemTransaction(ctx, system.runtime, nil)
	}
	return golemruntime.SystemTransaction(ctx, system.runtime, func(inner *golemruntime.SystemTx[P, Actor]) error {
		result := &SystemTx[P]{runtime: inner}
		result.Teams = SystemTxTeamClient[P]{runtime: inner}
		result.Invites = SystemTxInviteClient[P]{runtime: inner}
		return callback(result)
	})
}
func (transaction *SystemTx[P]) Enqueue(ctx context.Context, pending queue.Pending) (queue.JobID, error) {
	if transaction == nil {
		return golemruntime.SystemTxEnqueue(ctx, (*golemruntime.SystemTx[P, Actor])(nil), pending)
	}
	return golemruntime.SystemTxEnqueue(ctx, transaction.runtime, pending)
}
